"""Export playable Taiko song folders generated by a checkpoint (for listening/playtesting).

For each requested Taiko-1000 test song: one ``.tja`` with every course generated by the
model (conditioned like the human course: tier, density, timing), the original audio as
``WAVE``, and the human ``.tja`` for side-by-side comparison.

    python export_playable.py --ckpt /content/runs/v1b-taiko/best.pt --songs 6 \
        --out /content/runs/v1b-taiko/playable
"""

from __future__ import annotations

import argparse
import re
from pathlib import Path

import numpy as np
import pyarrow.parquet as pq
import torch
from huggingface_hub import HfApi, hf_hub_download

from urfm.codecs import get
from urfm.data.features import MEL
from urfm.ir.chart import AudioRef, ChartSet, Difficulty, SongMeta
from urfm.ir.serialize import from_msgpack
from urfm.tokenize import build_tokenizer
from urfm.tokenize.tokenizer import onset_rate
from urfm.train.data import shard_files
from urfm.train.generate import Job, generate
from urfm.train.tiers import chart_prefix, load_tiers
from urfm.train.train import load_checkpoint

TAIKO_REPO = "JacobLinCool/taiko-1000-parsed-clean"
TAIKO_REV = "b72da4616d643018e81f372cea06ce51349285e0"


def original_rows(split: str) -> list[dict]:
    """Rows of the source dataset in the order ingest numbered them (``<split>-<index>``)."""
    files = sorted(
        f
        for f in HfApi().list_repo_files(TAIKO_REPO, repo_type="dataset", revision=TAIKO_REV)
        if f.startswith(f"data/{split}-")
    )
    rows: list[dict] = []
    for name in files:
        path = hf_hub_download(TAIKO_REPO, name, repo_type="dataset", revision=TAIKO_REV)
        rows += pq.read_table(path, columns=["audio", "tja"]).to_pylist()
    return rows


def main() -> int:
    ap = argparse.ArgumentParser()
    ap.add_argument("--ckpt", required=True)
    ap.add_argument("--data", default="/content/data/urfm-ingest-v0")
    ap.add_argument("--split", default="test")
    ap.add_argument("--songs", type=int, default=6)
    ap.add_argument("--skip", type=int, default=0)
    ap.add_argument("--tag", default="URFM")
    ap.add_argument("--temperature", type=float, default=0.85)
    ap.add_argument("--plan", default="calibrated", choices=["calibrated", "sample", "mean"])
    ap.add_argument("--out", required=True)
    args = ap.parse_args()

    device = "cuda" if torch.cuda.is_available() else "cpu"
    model, meta = load_checkpoint(args.ckpt, device)
    tiers = load_tiers(meta)
    tok = build_tokenizer()
    source = original_rows(args.split)

    picked = []
    for file in shard_files(args.data, ["taiko1000"], args.split):
        table = pq.read_table(file, columns=["song_id", "mel", "chartset"])
        for sid, mel, blob in zip(*(table[c].to_pylist() for c in table.column_names), strict=True):
            picked.append((sid, mel, blob))
    picked = picked[args.skip : args.skip + args.songs]

    tja = get("tja")
    out_root = Path(args.out)
    for sid, mel, blob in picked:
        cs = from_msgpack(blob)
        charts = [c for c in cs.charts if c.events and c.mechanics == "taiko"]
        mel_arr = np.frombuffer(mel, np.uint8).reshape(-1, MEL.n_mels)
        jobs = [
            Job(
                mel=mel_arr,
                timing=cs.timing_of(c),
                mechanics="taiko",
                prefix=chart_prefix(tok, tiers, cs, c),
                difficulty=Difficulty(label=c.difficulty.label, level=c.difficulty.level),
                target_rate=onset_rate(cs, c),
            )
            for c in charts
        ]
        generated = generate(
            model, tok, jobs, temperature=args.temperature, device=device, plan=args.plan
        )

        index = int(sid.rsplit("-", 1)[1])
        row = source[index]
        ext = Path(row["audio"].get("path") or "song.ogg").suffix or ".ogg"
        folder = out_root / re.sub(r"[^\w.-]+", "_", f"{sid}-{cs.song.title}")[:80]
        folder.mkdir(parents=True, exist_ok=True)
        (folder / f"song{ext}").write_bytes(row["audio"]["bytes"])
        human_tja = re.sub(r"(?m)^WAVE:.*$", f"WAVE:song{ext}", row["tja"])
        (folder / "human.tja").write_text(human_tja, encoding="utf-8")

        song = SongMeta(
            title=f"{cs.song.title} ({args.tag})",
            subtitle=cs.song.subtitle,
            artist=cs.song.artist,
            preview=cs.song.preview,
        )
        out = ChartSet(
            timing=cs.timing, charts=tuple(generated), song=song, audio=AudioRef(path=f"song{ext}")
        )
        (folder / "urfm.tja").write_bytes(tja.write(out))
        counts = {c.difficulty.label: len(c.events) for c in generated}
        human = {c.difficulty.label: len(c.events) for c in charts}
        print(f"{folder.name}: generated {counts} human {human}", flush=True)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
